% Program 13.2 Successive Parabolic Interpolation
% Input: inline function f, initial guesses r,s,t, number of steps k
% Output: approximate minimum x
function x=spi(f,r,s,t,k)
x(1)=r;x(2)=s;x(3)=t;
fr=f(r);fs=f(s);ft=f(t);
for i=4:k+3
  x(i)=(r+s)/2-(fs-fr)*(t-r)*(t-s)/(2*((s-r)*(ft-fs)-(fs-fr)*(t-s)));
  t=s;s=r;r=x(i);
  ft=fs;fs=fr;fr=f(r);            % single function evaluation
end

%Program 3.6 Cubic spline plot
%Computes and plots spline from data points
%Input: x,y vectors of data points, k number of plotted points 
%   per segment
%Output: x1,y1 spline values at plotted points
function [x1,y1]=splineplot(x,y,k)
n=length(x); 
coeff=splinecoeff(x,y);
x1=[];y1=[];
for i=1:n-1           
    xs=linspace(x(i),x(i+1),k+1);
    dx=xs-x(i);
    ys=coeff(i,3)*dx; % evaluate using nested multiplication
    ys=(ys+coeff(i,2)).*dx;
    ys=(ys+coeff(i,1)).*dx+y(i);
    x1=[x1;xs(1:k)'];y1=[y1;ys(1:k)'];
end
x1=[x1;x(end)];y1=[y1;y(end)];

